module ptx_ldpc_hdr (
  input  wire [3:0]  addr,      // {CBS code (2), rate code (2)}
  output reg  [9:0]  base,
  output reg  [7:0]  nnz,
  output reg  [6:0]  h0s,       // shift of the p0 circulant in row 0
  output reg  [3:0]  hxr,       // the other row (x) of the p0 column
  output reg  [6:0]  hxs,
  output reg  [6:0]  hroll);    // p0 = rot(sum of lambda, hroll)
  always @* case (addr)
    4'd0: begin base = 10'd0; nnz = 8'd63; h0s = 7'd1; hxr = 4'd6; hxs = 7'd0; hroll = 7'd0; end
    4'd1: begin base = 10'd63; nnz = 8'd71; h0s = 7'd1; hxr = 4'd4; hxs = 7'd0; hroll = 7'd0; end
    4'd2: begin base = 10'd134; nnz = 8'd75; h0s = 7'd1; hxr = 4'd3; hxs = 7'd0; hroll = 7'd0; end
    4'd3: begin base = 10'd209; nnz = 8'd79; h0s = 7'd1; hxr = 4'd2; hxs = 7'd0; hroll = 7'd0; end
    4'd4: begin base = 10'd288; nnz = 8'd61; h0s = 7'd1; hxr = 4'd6; hxs = 7'd0; hroll = 7'd0; end
    4'd5: begin base = 10'd349; nnz = 8'd71; h0s = 7'd1; hxr = 4'd4; hxs = 7'd0; hroll = 7'd0; end
    4'd6: begin base = 10'd420; nnz = 8'd75; h0s = 7'd1; hxr = 4'd3; hxs = 7'd0; hroll = 7'd0; end
    4'd7: begin base = 10'd495; nnz = 8'd76; h0s = 7'd1; hxr = 4'd2; hxs = 7'd0; hroll = 7'd0; end
    4'd8: begin base = 10'd571; nnz = 8'd61; h0s = 7'd1; hxr = 4'd6; hxs = 7'd0; hroll = 7'd0; end
    4'd9: begin base = 10'd632; nnz = 8'd71; h0s = 7'd1; hxr = 4'd4; hxs = 7'd0; hroll = 7'd0; end
    4'd10: begin base = 10'd703; nnz = 8'd72; h0s = 7'd1; hxr = 4'd3; hxs = 7'd0; hroll = 7'd0; end
    4'd11: begin base = 10'd775; nnz = 8'd70; h0s = 7'd1; hxr = 4'd2; hxs = 7'd0; hroll = 7'd0; end
    default: begin base = 10'd0; nnz = 8'd0; h0s = 7'd0; hxr = 4'd0; hxs = 7'd0; hroll = 7'd0; end
  endcase
endmodule

